import Header from "@/components/Header";
import Footer from "@/components/Footer";
import { getContentEntries } from "@/lib/content";

export const revalidate = 60;

export default async function Menciones() {
  const entries = await getContentEntries("mentions");

  return (
    <>
      <Header />
      <main className="editorial">
        <div className="container editorial-grid">
          {entries.map((entry) => (
            <article className="editorial-card" key={entry.id}>
              {entry.image_url && (
                <div className="editorial-image-wrap">
                  <img src={entry.image_url} alt={entry.title} />
                </div>
              )}

              <h2>{entry.title}</h2>
              {entry.subtitle && <p className="editorial-subtitle">{entry.subtitle}</p>}
              {entry.body && <p>{entry.body}</p>}

              {entry.link_url && (
                <a
                  className="btn-soft"
                  href={entry.link_url}
                  target="_blank"
                  rel="noreferrer"
                >
                  {entry.link_label || "Ver publicación"}
                </a>
              )}
            </article>
          ))}

          {!entries.length && (
            <p>No hay menciones cargadas todavía.</p>
          )}
        </div>
      </main>
      <Footer />
    </>
  );
}
